mapper.select:
SELECT 
FROM guestbook
WHERE parent_id IS NULL
AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}

SELECT 
FROM guestbook
WHERE parent_id IS NULL
  AND (
    user_id = #{userId}
    OR id IN (
      SELECT parent_id FROM guestbook
      WHERE user_id = #{userId} AND parent_id IS NOT NULL
    )
  )
AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}

